package dev.trentdb.storage;import dev.trentdb.storage.format.*;import java.util.*;public final class DuckDbPrimitiveSegmentScan implements Iterator<DuckDbPrimitiveSegmentScan.Vector>{private final DuckDbPrimitivePayloadReader payload;private final DuckDbTableCreateInfo.ScalarLogicalType type;private final List<DuckDbPrimitiveColumnMetadata.Segment> data,validity;private final long rows;private int index;private long position;public DuckDbPrimitiveSegmentScan(SingleFileBlockManager m,DuckDbTableCreateInfo.ScalarLogicalType type,List<DuckDbPrimitiveColumnMetadata.Segment> data,List<DuckDbPrimitiveColumnMetadata.Segment> validity,long rows){this.payload=new DuckDbPrimitivePayloadReader(m);this.type=type;this.data=List.copyOf(data);this.validity=List.copyOf(validity);this.rows=rows;if(rows<0||(!validity.isEmpty()&&data.size()!=validity.size()))throw new StorageFormatException("DuckDB primitive segment scan descriptors are not aligned");long total=0;for(int i=0;i<data.size();i++){var d=data.get(i);if(d.tupleCount()<0||d.tupleCount()>DuckDbPrimitivePayloadReader.VECTOR_SIZE||(!validity.isEmpty()&&validity.get(i).tupleCount()!=d.tupleCount()))throw new StorageFormatException("DuckDB primitive segment scan descriptor count is invalid");total=Math.addExact(total,d.tupleCount());}if(total!=rows)throw new StorageFormatException("DuckDB primitive segment scan row count has a gap or overlap");}public boolean hasNext(){return index<data.size();}public Vector next(){if(!hasNext())throw new NoSuchElementException();var values=payload.read(type,data.get(index),validity.isEmpty()?null:validity.get(index));var v=new Vector(position,values);position+=values.size();index++;return v;}public record Vector(long rowStart,List<Long> values){public Vector{values=Collections.unmodifiableList(new ArrayList<>(values));}}}
